WITH metrics AS (SELECT id, store_id, order_date, status, channel, amount, discount, LAG(amount) OVER w_ordered AS prev_amount, LEAD(amount) OVER w_ordered AS next_amount, LAG(shipping_fee) OVER w_ordered AS prev_shipping_fee, ROW_NUMBER() OVER w_ordered AS row_seq, SUM(discount) OVER (ORDER BY shipping_fee, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_discount FROM orders WINDOW w_ordered AS (PARTITION BY customer_id ORDER BY shipping_fee, id)) SELECT id, order_date, status, channel, discount, prev_amount, next_amount, row_seq, running_discount, CASE WHEN channel RLIKE '^(web|store)$' THEN 'EXTENDED' WHEN channel RLIKE '^(mobile|partner)$' THEN 'OTHER_ZONE' ELSE 'PRIORITY' END AS channel_zone FROM metrics ORDER BY order_date DESC
